    #[test]
    fn test_parameter_manifold_gradient_step() {
        let mut pm = ParameterManifold::new(DVector::from_vec(vec![1.0, 2.0, 3.0]), 0.1);
        pm.set_gradient(DVector::from_vec(vec![1.0, 0.0, -1.0]));
        let new_theta = pm.gradient_step();
        assert!((new_theta[0] - 0.9).abs() < 1e-10);
        assert!((new_theta[2] - 3.1).abs() < 1e-10);
    }

    #[test]
    fn test_parameter_manifold_natural_gradient() {
        let mut pm = ParameterManifold::new(DVector::from_vec(vec![1.0, 1.0]), 0.1);
        pm.set_fisher(DMatrix::from_row_slice(2, 2, &[2.0, 0.0, 0.0, 2.0]));
        pm.set_gradient(DVector::from_vec(vec![2.0, 2.0]));
        let new_theta = pm.natural_gradient_step();
        // F^{-1} g = [1/2, 1/2], step = 0.1 * [1/2, 1/2] = [0.05, 0.05]
        assert!((new_theta[0] - 0.9).abs() < 0.01);
    }

    #[test]
    fn test_riemannian_gradient() {
        let mut pm = ParameterManifold::new(DVector::from_vec(vec![0.0; 3]), 0.1);
        pm.set_fisher(DMatrix::from_diagonal(&DVector::from_vec(vec![2.0, 4.0, 1.0])));
        pm.set_gradient(DVector::from_vec(vec![2.0, 4.0, 1.0]));
        let rg = pm.riemannian_gradient();
        assert!((rg[0] - 1.0).abs() < 1e-10);
        assert!((rg[1] - 1.0).abs() < 1e-10);
        assert!((rg[2] - 1.0).abs() < 1e-10);
    }

    #[test]
    fn test_riemannian_norm() {
        let mut pm = ParameterManifold::new(DVector::from_vec(vec![0.0; 2]), 0.1);
        pm.set_fisher(DMatrix::from_row_slice(2, 2, &[1.0, 0.0, 0.0, 4.0]));
        let v = DVector::from_vec(vec![1.0, 1.0]);
        let norm = pm.riemannian_norm(&v);
        // v^T F v = 1*1 + 4*1 = 5, sqrt(5)
        assert!((norm - 5.0_f64.sqrt()).abs() < 1e-10);
    }

    #[test]
    fn test_parameter_manifold_identity_fisher() {
        let mut pm = ParameterManifold::new(DVector::from_vec(vec![1.0, 2.0]), 0.1);
        pm.set_gradient(DVector::from_vec(vec![1.0, 1.0]));
        let rg = pm.riemannian_gradient();
        assert!((rg[0] - 1.0).abs() < 1e-10);
        assert!((rg[1] - 1.0).abs() < 1e-10);
    }

