    #[test]
    fn test_log_sobolev_verify_lsi() {
        let ls = LogSobolev::from_curvature(2.0);
        let mu = Density::gaussian(1, 21, 0.1, 0.5);
        // Simple test function: f = x (linear)
        let half = 10.0;
        let f: Vec<f64> = (0..21).map(|i| (i as f64 - half) * 0.1).collect();
        let (ent, dir, ratio) = ls.verify_lsi(&f, &mu);
        assert!(ent.is_finite());
        assert!(dir >= 0.0);
    }

