    #[test]
    fn test_convergence_report_serde() {
        let report = ConvergenceReport {
            curvature_k: 5.0,
            spectral_gap: 5.0,
            w2_contraction: 0.1,
            entropy_decay: 0.01,
            log_sobolev_constant: 0.4,
            time: 1.0,
        };
        let json = serde_json::to_string(&report).unwrap();
        let back: ConvergenceReport = serde_json::from_str(&json).unwrap();
        assert!((back.curvature_k - 5.0).abs() < 1e-10);
        assert!((back.time - 1.0).abs() < 1e-10);
    }

    // ─── Integration Tests ───────────────────────────────

    #[test]
    fn test_full_pipeline_kimi_theorem() {
        // Full pipeline: potential → FP → BE → spectral gap → contraction → PLATO
        let dim = 1;
        let grid = 21;
        let spacing = 0.1;
        let k = 5.0;
        let diffusion = 0.5;

        // 1. Create potential
        let pot = Potential::quadratic(dim, grid, spacing, k);

        // 2. Verify CD(K,∞)
        let be = BakryEmery::new(pot.clone());
        assert!(be.check_cd(k * 0.8));

        // 3. FP evolve
        let fp = FokkerPlanck::new(pot.clone(), diffusion);
        let rho = Density::gaussian(dim, grid, spacing, 2.0);
        let gibbs = fp.gibbs_measure();
        let evolved = fp.evolve(&rho, 0.1, 50);

        // 4. KL divergence should decrease
        let kl0 = rho.kl_divergence(&gibbs);
        let kl1 = evolved.kl_divergence(&gibbs);
        assert!(kl1 < kl0, "KL should decrease: {} → {}", kl0, kl1);

        // 5. Spectral gap ≥ K
        let sge = SpectralGapEstimator::new(pot.clone(), diffusion);
        assert!(sge.be_lower_bound() >= k * 0.5);

        // 6. PLATO convergence
        let plato = PlatoBeliefUpdate::new(k, diffusion, dim, grid, spacing);
        let report = plato.convergence_analysis(1.0);
        assert!(report.w2_contraction < 1.0);
    }

    #[test]
    fn test_integration_jko_fp_agreement() {
        // JKO and FP should give similar results for small τ
        let pot = Potential::quadratic(1, 11, 0.5, 3.0);
        let diffusion = 0.5;
        let rho = Density::gaussian(1, 11, 0.5, 1.0);

        let fp = FokkerPlanck::new(pot.clone(), diffusion);
        let fp_result = fp.evolve(&rho, 0.01, 5);

        let jko = JKOScheme::new(pot, diffusion, 0.002);
        let jko_result = jko.evolve(&rho, 5);

        // Both should produce valid densities
        assert!((fp_result.total_mass() - 1.0).abs() < 0.5);
        assert!((jko_result.total_mass() - 1.0).abs() < 0.5);
    }

    #[test]
    fn test_integration_fisher_ricci_natural_gradient() {
        // Natural gradient descent uses Fisher metric → connects to Ricci curvature
        let theta = DVector::from_vec(vec![1.0, -1.0]);
        let mut pm = ParameterManifold::new(theta, 0.1);

        let fisher = DMatrix::from_row_slice(2, 2, &[3.0, 0.5, 0.5, 3.0]);
        pm.set_fisher(fisher.clone());
        pm.set_gradient(DVector::from_vec(vec![3.0, -3.0]));

        let rg = pm.riemannian_gradient();
        let _new_theta = pm.natural_gradient_step();

        let fr = FisherRicci::from_fisher(fisher);
        let sc = fr.scalar_curvature();
        // Zero Christoffel for constant Fisher
        assert!(sc.abs() < 1e-10);
    }
